// Some portions generated by Claude
import { RDF_TYPE } from "./graph-canvas-scope.ts";
import type { GraphEdge, GraphNode, GraphNodeType } from "./graph-types.ts";

export type DetailsGroup = {
  predicate: string;
  label: string;
  items: GraphNode[];
};

export type LinkGroup = DetailsGroup & { direction: "outgoing" | "incoming" };

export type NodeDetails = {
  types: GraphNodeType[];
  values: DetailsGroup[];
  links: LinkGroup[];
};

/** The node's loaded data as the details card shows it: types, literal values and linked resources per predicate. */
export function nodeDetails(
  node: GraphNode,
  edges: readonly GraphEdge[],
  nodeById: ReadonlyMap<string, GraphNode>,
): NodeDetails {
  const values = new Map<string, DetailsGroup>();
  const outgoing = new Map<string, LinkGroup>();
  const incoming = new Map<string, LinkGroup>();
  const linkedTypes: GraphNodeType[] = [];
  const lookup = (id: string): GraphNode => nodeById.get(id) ?? { id, label: id, kind: "iri" };
  edges.forEach((edge) => {
    if (edge.source === node.id) {
      const target = lookup(edge.target);
      if (edge.predicate === RDF_TYPE) linkedTypes.push({ id: target.id, label: target.label });
      else if (target.kind === "literal") addTo(values, edge, target, {});
      else addTo(outgoing, edge, target, { direction: "outgoing" });
    } else if (edge.target === node.id && edge.predicate !== RDF_TYPE) {
      addTo(incoming, edge, lookup(edge.source), { direction: "incoming" });
    }
  });
  return {
    types: node.types?.length ? node.types : linkedTypes,
    values: [...values.values()],
    links: [...outgoing.values(), ...incoming.values()],
  };
}

function addTo<Extra extends object>(
  groups: Map<string, DetailsGroup & Extra>,
  edge: GraphEdge,
  item: GraphNode,
  extra: Extra,
) {
  const group = groups.get(edge.predicate);
  if (group) group.items.push(item);
  else groups.set(edge.predicate, { predicate: edge.predicate, label: edge.label, items: [item], ...extra });
}
